from pydantic import BaseModel, Field
from typing import Optional, List

class SQLAgentOutput(BaseModel):
    """Structured response schema generated by the SQL Agent."""
    reasoning: str = Field(description="Step-by-step logic explaining why this SQL query was chosen.")
    sql_query: str = Field(description="Executable SQL query tailored for DuckDB/SQLite syntax.")
    tables_used: List[str] = Field(default_factory=list, description="List of tables referenced in the query.")

class PythonAgentOutput(BaseModel):
    """Structured response schema generated by the Python Analytical Agent."""
    reasoning: str = Field(description="Analytical approach and data transformation strategy.")
    python_code: str = Field(description="Executable Pandas/Python code snippet to run inside the E2B sandbox.")
    expected_output_type: str = Field(description="Summary of expected output: dataframe, plot, or scalar metric.")